/**
 * Core component that provides access to time slot info via render props.
 * Includes start/end dates, duration, bookable status, and selection state.
 *
 * @component
 * @example
 * ```tsx
 * <TimeSlot.Info>
 *   {({ startDate, endDate, durationInMinutes, bookable, isSelected }) => (
 *     <div>
 *       <span>{startDate}</span>
 *       <span>{durationInMinutes} min</span>
 *     </div>
 *   )}
 * </TimeSlot.Info>
 * ```
 */
export function Info(props) {
    const timeSlotService = useService(TimeSlotServiceDefinition);
    const timeSlot = timeSlotService.timeSlotSignal.get();
    const bookingService = useService(BookingServiceDefinition);
    const selectedTimeSlot = bookingService.serviceSelections.get()[0]?.timeSlot;
    const isSelected = selectedTimeSlot?.startDate === timeSlot.localStartDate &&
        selectedTimeSlot?.location?._id === timeSlot.location?._id;
    const startDate = new Date(timeSlot.localStartDate);
    const endDate = new Date(timeSlot.localEndDate);
    const locationName = timeSlot.location?.name ?? '';
    const bookable = timeSlot.bookable ?? false;
    const durationInMinutes = Math.round((endDate.getTime() - startDate.getTime()) / (1000 * 60));
    return props.children({
        startDate,
        endDate,
        durationInMinutes,
        locationName,
        bookable,
        isSelected,
        timeSlot,
    });
}
/**
 * Core component that provides slot actions via render props.
 *
 * @component
 * @example
 * ```tsx
 * <TimeSlot.Actions>
 *   {({ selectSlot, isSelected, bookable, clearPreferences, shouldShowClearPreferences }) => (
 *     <div>
 *       <button onClick={selectSlot} disabled={!bookable}>
 *         {isSelected ? 'Selected' : 'Select'}
 *       </button>
 *       {shouldShowClearPreferences && (
 *          <button onClick={clearPreferences}>Change</button>
 *       )}
 *     </div>
 *   )}
 * </TimeSlot.Actions>
 * ```
 */
export function Actions(props) {
    const timeSlotService = useService(TimeSlotServiceDefinition);
    const timeSlot = timeSlotService.timeSlotSignal.get();
    const service = useService(TimeSlotListServiceDefinition);
    const bookingService = useService(BookingServiceDefinition);
    const selectedTimeSlot = bookingService.serviceSelections.get()[0]?.timeSlot;
    const isSelected = selectedTimeSlot?.startDate === timeSlot.localStartDate &&
        selectedTimeSlot?.location?._id === timeSlot.location?._id;
    const selectTimeSlot = () => {
        service.actions.selectSlot(timeSlot);
    };
    const bookable = timeSlot.bookable ?? false;
    const selectedStaffMemberId = bookingService.serviceSelections.get()[0]?.timeSlot?.resources?.[0]?._id;
    const staffFromSlot = timeSlot.availableResources[0].resources.map((r) => r._id);
    const shouldShowClearStaffSelection = !!selectedStaffMemberId && staffFromSlot.length > 1;
    const clearStaffSelection = shouldShowClearStaffSelection
        ? service.actions.clearStaffSelection
        : undefined;
    return props.children({
        selectTimeSlot,
        clearStaffSelection,
        timeSlot,
        bookable,
        isSelected,
    });
}
/**
 * Core component that provides access to time slot staff members via render props.
 * Extracts unique staff members from slot.staffByLocation (names already included).
 * Each staff member includes isSelected based on current selection state.
 *
 * Returns null if there's only 1 staff member (nothing to choose from).
 *
 * @component
 * @example
 * ```tsx
 * <CoreTimeSlot.StaffMembers>
 *   {({ staffMembers, selectStaffMember }) => (
 *     <GenericList.Root items={staffMembers}>
 *       {children}
 *     </GenericList.Root>
 *   )}
 * </CoreTimeSlot.StaffMembers>
 * ```
 */
export function StaffMembers(props) {
    const timeSlotService = useService(TimeSlotServiceDefinition);
    const timeSlot = timeSlotService.timeSlotSignal.get();
    const service = useService(TimeSlotListServiceDefinition);
    const bookingService = useService(BookingServiceDefinition);
    const selectedStaffMemberId = bookingService.serviceSelections.get()[0]?.timeSlot?.resources?.[0]?._id;
    const staffMembers = timeSlot.availableResources[0].resources;
    if (staffMembers.length <= 1) {
        return null;
    }
    const staffMembersData = staffMembers.map((s) => ({
        id: s._id,
        name: s.name,
        isSelected: selectedStaffMemberId === s._id,
    }));
    return props.children({
        staffMembers: staffMembersData,
        selectStaffMember: service.actions.selectStaffMember,
    });
}
/**
 * Core component that provides access to staff member info via render props.
 * Must be used within StaffMemberProvider.
 *
 * @component
 * @example
 * ```tsx
 * <StaffMemberInfo>
 *   {({ name, isSelected }) => (
 *     <span>{name}</span>
 *   )}
 * </StaffMemberInfo>
 * ```
 */
export function StaffMemberInfo(props) {
    const { staffMember } = useStaffMemberContext();
    return props.children({
        name: staffMember.name,
        isSelected: staffMember.isSelected,
        staffMember,
    });
}
/**
 * Core component that provides staff member actions via render props.
 * Must be used within StaffMemberProvider.
 *
 * @component
 * @example
 * ```tsx
 * <StaffMemberActions>
 *   {({ selectStaffMember, isSelected }) => (
 *     <button onClick={selectStaffMember}>
 *       {isSelected ? 'Selected' : 'Select'}
 *     </button>
 *   )}
 * </StaffMemberActions>
 * ```
 */
export function StaffMemberActions(props) {
    const { staffMember, selectStaffMember } = useStaffMemberContext();
    return props.children({
        selectStaffMember,
        isSelected: staffMember.isSelected,
        staffMember,
    });
}
